-- 2026-10-29 | Source Two / Policies | READ ONLY
-- Recover the exact field names from the policy record returned by SQL 16.
-- RERUN the SELECT GENERATED by SQL 16 Query 4 for ContentId 7250127,
-- then IMMEDIATELY run only this SELECT in the same Snowflake session.
-- RESULT_SCAN(LAST_QUERY_ID()) requires that SELECT to be the latest query.
-- Alternative: replace LAST_QUERY_ID() with 'actual Snowsight query ID'
-- obtained from Query History; the result must be within 24 hours.
-- No table writes. No guessed Policy Level 3 NAME or metadata table.
-- Note: 7250127 is only the policy record the owner examined. Before
-- asserting a link to Source 185810 verify this ID occurs in its reference array.
WITH policy_result AS (
  SELECT POLICY_CONTENT_ID::VARCHAR AS POLICY_CONTENT_ID,
         IFF(TYPEOF(POLICY_JSON)='VARCHAR',
             TRY_PARSE_JSON(POLICY_JSON::VARCHAR), POLICY_JSON) AS POLICY_OBJECT
  FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
  WHERE POLICY_CONTENT_ID::VARCHAR='7250127'
),
fields AS (
  SELECT p.POLICY_CONTENT_ID, k.KEY::VARCHAR AS ACTUAL_ARCHER_FIELD,
         k.VALUE AS FIELD_VALUE, TYPEOF(k.VALUE) AS STORED_FIELD_TYPE,
         COALESCE(TRY_PARSE_JSON(k.VALUE::VARCHAR),k.VALUE) AS NORMALIZED_VALUE
  FROM policy_result p,
       LATERAL FLATTEN(INPUT=>p.POLICY_OBJECT) k
),
items AS (
  SELECT f.*, ref.VALUE AS REFERENCE_ITEM,
         ref.VALUE:ContentId::VARCHAR AS REFERENCED_CONTENT_ID,
         ref.VALUE:LevelId::VARCHAR AS REFERENCED_LEVEL_ID
  FROM fields f,
       LATERAL FLATTEN(
         INPUT=>IFF(IS_ARRAY(f.NORMALIZED_VALUE),
                    f.NORMALIZED_VALUE,ARRAY_CONSTRUCT()),
         OUTER=>TRUE
       ) ref
)
SELECT POLICY_CONTENT_ID, ACTUAL_ARCHER_FIELD, STORED_FIELD_TYPE,
       FIELD_VALUE,
       REFERENCED_CONTENT_ID, REFERENCED_LEVEL_ID,
       CASE
         WHEN REFERENCED_CONTENT_ID IS NOT NULL
          AND REFERENCED_LEVEL_ID IS NOT NULL
           THEN 'ARCHER_RECORD_REFERENCE_NOT_RESOLVED'
         WHEN REFERENCE_ITEM IS NOT NULL AND IS_ARRAY(NORMALIZED_VALUE)
           THEN 'ARRAY_ITEM_CHECK_TYPE_OR_NUMERIC_REFERENCE'
         WHEN ACTUAL_ARCHER_FIELD ILIKE '%NAME%'
           THEN 'NAME_FIELD_CHECK_VALUE'
         ELSE 'SCALAR_OR_OTHER_FIELD'
       END AS FIELD_CLASS
FROM items
WHERE REGEXP_LIKE(ACTUAL_ARCHER_FIELD,
                 '.*(NAME|NUMBER|TITLE|POLICY|REFERENCE|PURPOSE|DESCRIPTION|STATUS).*','i')
ORDER BY ACTUAL_ARCHER_FIELD, REFERENCED_CONTENT_ID
LIMIT 250;
